import {content,T,saveContent,resetContent} from './content.js';
const $=id=>document.getElementById(id),original=new WeakMap();
function translate(n){if(n.nodeType===3){if(!n.parentElement||n.parentElement.closest('#copy-panel,script,style,textarea'))return;const prev=original.get(n),raw=prev&&n.textContent===prev.out?prev.raw:n.textContent,out=raw.replace(raw.trim(),T(raw.trim()));original.set(n,{raw,out});if(n.textContent!==out)n.textContent=out;}else if(n.nodeType===1||n.nodeType===9)for(const c of n.childNodes)translate(c);}
translate(document.body);document.title=content.title;new MutationObserver(rs=>{for(const r of rs)if(r.type==='characterData')translate(r.target);else for(const n of r.addedNodes)translate(n);}).observe(document.body,{childList:true,subtree:true,characterData:true});
const panel=$('copy-panel'),fields=$('copy-fields');let rows=[];try{rows=await fetch('content/labels.json').then(r=>r.json());}catch{}
function field(label,value,key,multi=false){const l=document.createElement('label'),s=document.createElement('span'),i=document.createElement(multi?'textarea':'input');s.textContent=label;i.value=value;i.dataset.key=key;if(multi)i.rows=6;l.append(s,i);fields.append(l);}
function populate(){fields.replaceChildren();for(const k of ['title','english','tagline'])field({title:'项目标题',english:'英文副标题',tagline:'开场副标题'}[k],content[k],k);content.poems.forEach((p,i)=>{field('第 '+(i+1)+' 场 · 诗句',p.text,'poem.'+i+'.text',true);field('第 '+(i+1)+' 场 · 署名',p.credit,'poem.'+i+'.credit');});const h=document.createElement('h3');h.textContent='按钮、招牌与其他文字';fields.append(h);rows.filter(r=>r.text&&!r.text.includes('${')&&!r.text.startsWith('{')).forEach(r=>field(r.group+' · '+r.text,T(r.text),'label.'+r.id,r.text.length>45));}
function collect(){const next=structuredClone(content);for(const i of fields.querySelectorAll('[data-key]')){const [k,n,p]=i.dataset.key.split('.');if(k==='poem')next.poems[+n][p]=i.value;else if(k==='label'){const row=rows.find(r=>r.id===n);if(i.value!==T(row.text))next.labels[row.text]=i.value;}else next[k]=i.value;}return next;}
for(const id of ['edit-copy','edit-copy-intro'])$(id)?.addEventListener('click',()=>{populate();panel.hidden=false;document.body.classList.add('editing-copy');});
$('copy-close').onclick=()=>{panel.hidden=true;document.body.classList.remove('editing-copy');};
$('copy-save').onclick=()=>{try{saveContent(collect());$('copy-feedback').textContent='已保存。重新进入后，招牌与界面文字会一起更新。';}catch{$('copy-feedback').textContent='未能保存，请先导出备份。';}};
$('copy-apply').onclick=()=>{saveContent(collect());location.reload();};
$('copy-reset').onclick=()=>{resetContent();populate();$('copy-feedback').textContent='已恢复本版本原文。';};
$('copy-export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(collect(),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='第十二个圣诞夜-文案.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('copy-import').onchange=async e=>{try{const d=JSON.parse(await e.target.files[0].text());if(typeof d.title!=='string'||!Array.isArray(d.poems)||d.poems.length!==6||d.poems.some(p=>typeof p.text!=='string'||typeof p.credit!=='string'))throw Error();saveContent({...content,...d});populate();$('copy-feedback').textContent='已导入，请点击“应用并重新进入”。';}catch{$('copy-feedback').textContent='请选择之前导出的文案 JSON 文件。';}};
